                    body.roomNumber,
                    body.guestName,
                    body.guestEmail,
                    body.guestCpf,
                    body.checkIn,
                    body.checkOut,
                    body.guests,
                    body.ratePlan,
                    body.companyCode
                );

                ctx.status(201);
